<?php
declare(strict_types=1);
namespace App\Jobs\QaReply;
use App\Enums\UserStatus; use Illuminate\Database\QueryException; use App\Models\QaReply; use App\Models\User; use App\Notifications\QaReplyReceivedNotification; use App\Services\Notifications\NotificationAttemptTracker; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\Middleware\WithoutOverlapping; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Notification; use Throwable;
final class QaReplyDatabaseNotificationJob implements ShouldQueue {use Dispatchable,Queueable,SerializesModels,InteractsWithQueue;public int $tries=0;public function __construct(public readonly string $replyId,public readonly string $recipientId){}public function backoff():array{return[60,300];}public function middleware():array{return[(new WithoutOverlapping('qa-reply-db:'.$this->replyId.':'.$this->recipientId))->releaseAfter(10)->expireAfter(300)];}public function handle():void{$r=QaReply::with('user')->find($this->replyId);$u=User::find($this->recipientId);if(!$r||!$u||$u->id===$r->user_id||$u->status!==UserStatus::InProgress)return;$id=self::notificationId($this->replyId,$this->recipientId);if($u->notifications()->whereKey($id)->exists())return;$count=app(NotificationAttemptTracker::class)->increment('qa_reply:'.$this->replyId,$this->recipientId,'database');if($count>3){$this->fail(new \RuntimeException('notification delivery attempts exceeded'));return;}try{$n=new QaReplyReceivedNotification($r);$n->id=$id;Notification::sendNow($u,$n,['database']);}catch(QueryException $e){if($e->getCode()==='23000' && (int)($e->errorInfo[1] ?? 0)===1062)return;throw $e;}catch(Throwable $e){if($count>=3){$this->fail($e);return;}throw $e;}}public static function notificationId(string $r,string $u):string{$h=hash('sha256','qa_reply:'.$r.':'.$u);return substr($h,0,8).'-'.substr($h,8,4).'-5'.substr($h,13,3).'-'.substr($h,16,4).'-'.substr($h,20,12);}}
